pub fn start_legacy_actor_scene(lua: &mlua::Lua) -> mlua::Result<()> {
    let root: mlua::Table = lua.globals().get("root")?;
    if root
        .raw_get::<Option<bool>>("__songlua_startup_commands_ran")?
        .unwrap_or(false)
    {
        return Ok(());
    }
    crate::lua_util::run_actor_named_command(lua, &root, "BeginCommand")?;
    crate::lua_util::run_named_command_on_children_recursively(lua, &root, "BeginCommand", None)?;
    crate::lua_util::run_actor_startup_commands_for_table(lua, &root)
}

pub fn advance_legacy_actor_scene(lua: &mlua::Lua, seconds: f64, delta: f64) -> mlua::Result<()> {
    let root: mlua::Value = lua.globals().get("root")?;
    crate::lua_util::set_live_frame(lua, seconds, seconds * 2.0, delta);
    crate::lua_util::run_actor_compile_update_functions_with_delta(lua, &root, delta)
}

